<?php
if(!defined('ABSPATH'))exit;if(!is_user_logged_in()){wp_safe_redirect(wp_login_url(home_url('/appointments-messages/')));exit;}$u=wp_get_current_user();$client=legacyx_find_client_by_wp_user(get_current_user_id());$appointments=$client?legacyx_get_client_appointments($client->ID):array();$messages=$client?legacyx_get_client_messages($client->ID):array();$counts=$client?legacyx_communication_counts($client->ID):array('appointments'=>0,'upcoming'=>0,'messages'=>0,'open_messages'=>0);get_header();?><main class="legacyx-credit-center"><div class="legacyx-credit-shell"><a class="legacyx-credit-back" href="<?php echo esc_url(home_url('/client-portal/'));?>">← Client Command Center</a><header class="legacyx-credit-head"><div><span class="kicker">LEGACY X FIRM OS · COMMUNICATIONS</span><h1>Appointments & Messages</h1><p>Your coordinated advisory schedule and client communication history.</p></div><div class="legacyx-credit-identity"><span>Client</span><strong><?php echo esc_html($u->display_name?:$u->user_login);?></strong></div></header><?php if(!$client):?><div class="legacyx-portal-notice"><strong>Communication workspace pending.</strong> Your Universal Client Profile must be linked first.</div><?php else:?><section class="legacyx-credit-summary"><div><span>Upcoming Meetings</span><strong><?php echo esc_html($counts['upcoming']);?></strong></div><div><span>Appointments</span><strong><?php echo esc_html($counts['appointments']);?></strong></div><div><span>Open Messages</span><strong><?php echo esc_html($counts['open_messages']);?></strong></div><div><span>Messages</span><strong><?php echo esc_html($counts['messages']);?></strong></div></section><section class="legacyx-credit-track"><div class="legacyx-track-title"><span>SCHEDULE</span><h2>Appointments</h2></div><div class="legacyx-step-list"><?php if(!$appointments):?><article class="legacyx-credit-step"><span class="legacyx-step-num">—</span><div><h3>No appointments scheduled</h3><p>Your advisory meetings will appear here when scheduled by the Legacy X Firm team.</p></div></article><?php else:foreach($appointments as $i=>$r):$status=get_post_meta($r->ID,'_legacyx_appointment_status',true);$date=get_post_meta($r->ID,'_legacyx_appointment_date',true);$time=get_post_meta($r->ID,'_legacyx_appointment_time',true);$type=get_post_meta($r->ID,'_legacyx_appointment_type',true);$advisor=get_post_meta($r->ID,'_legacyx_advisor',true);$loc=get_post_meta($r->ID,'_legacyx_meeting_location',true);$note=get_post_meta($r->ID,'_legacyx_client_note',true);?><article class="legacyx-credit-step"><span class="legacyx-step-num"><?php echo sprintf('%02d',$i+1);?></span><div><h3><?php echo esc_html(get_the_title($r));?></h3><p><strong><?php echo esc_html($status?:'Scheduled');?></strong> · <?php echo esc_html(trim($date.' '.$time));?><?php if($type):?> · <?php echo esc_html($type);?><?php endif;?><?php if($advisor):?><br><strong>Advisor:</strong> <?php echo esc_html($advisor);?><?php endif;?><?php if($loc):?><br><strong>Location:</strong> <?php echo esc_html($loc);?><?php endif;?><?php if($note):?><br><?php echo esc_html($note);?><?php endif;?></p></div><b>→</b></article><?php endforeach;endif;?></div></section><section class="legacyx-credit-track"><div class="legacyx-track-title"><span>COMMUNICATIONS</span><h2>Messages</h2></div><div class="legacyx-step-list"><?php if(!$messages):?><article class="legacyx-credit-step"><span class="legacyx-step-num">—</span><div><h3>No messages yet</h3><p>Client-visible Legacy X Firm communications will appear here.</p></div></article><?php else:foreach($messages as $i=>$r):$direction=get_post_meta($r->ID,'_legacyx_direction',true);$status=get_post_meta($r->ID,'_legacyx_message_status',true);$body=get_post_meta($r->ID,'_legacyx_message_body',true);?><article class="legacyx-credit-step"><span class="legacyx-step-num"><?php echo sprintf('%02d',$i+1);?></span><div><h3><?php echo esc_html(get_the_title($r));?></h3><p><strong><?php echo esc_html($direction);?></strong> · <?php echo esc_html($status?:'Open');?><br><?php echo nl2br(esc_html($body));?></p></div></article><?php endforeach;endif;?></div></section><?php endif;?></div></main><?php get_footer();?>